export const ARTICLES: Article[] = META.map((m) => ({
  ...m,
  text: (bare as Record<string, string>)[m.id] || m.title,
}))

export function articleById(id: string) {
  return ARTICLES.find((a) => a.id.toLowerCase() === id.toLowerCase())
}

export function articleTopicId(articleId: string) {
  return `art-${articleId.toLowerCase()}`
}

export function articleIdFromTopicId(topicId: string): string | null {
  const match = topicId.match(/^art-(\d+[a-z]{0,3})$/i)
  if (!match?.[1]) return null
  const raw = match[1]
  const m = raw.match(/^(\d+)([a-z]*)$/i)
  if (!m) return raw.toUpperCase()
  return `${m[1]}${m[2].toUpperCase()}`
}

export function articlesInPart(part: string) {
  return ARTICLES.filter((a) => a.part === part)
}

/** True when `hay` names this article as a whole token (21 ≠ 21A ≠ 217). */
export function mentionsArticle(hay: string, id: string) {
  const escaped = id.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")
  return new RegExp(`(^|[^0-9A-Za-z])${escaped}(?![0-9A-Za-z])`, "i").test(hay)
}

